/*common.coco.selectScmList*/
SELECT
	  NVL(DS_DELAY_REASON,'') AS DS_DELAY_REASON -- 협력사지연사유
	, NVL(DELAY_REMARK,'') AS DELAY_REMARK -- 물류센터지연사유
	, NVL(SCM_REMARK,'') AS SCM_REMARK
FROM ICOMPODT
WHERE
		BUYER = #{st_buyer}
	AND PO_NO = #{st_po_no}
	AND PO_SEQ = #{st_po_seq}

mapper.update:

/*updateCommonCoCoScmActionDetailPop*/
UPDATE ICOMPODT
SET
	SCM_REMARK = SCM_REMARK||'^^'||TO_CHAR(SYSDATE,'YYYYMMDD')||'@@'||#{st_user_name}||'@@'||#{st_scm_remark}
WHERE
		BUYER = #{st_buyer}
	AND PO_NO = #{st_po_no}



	AND PO_SEQ = #{st_po_seq}


/*updateCommonCoCoScmActionPors*/
UPDATE ICOMPORS
SET
	ADMIN_FLAG1 = 'Y'
WHERE
		BUYER = #{st_buyer}
	AND PO_NO = #{st_po_no}



	AND PO_SEQ = #{st_po_seq}
